import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Список Предложений по Расширенным Настройкам","description":"","frontmatter":{},"headers":[],"relativePath":"ru/98-扩展设定建议清单.md","filePath":"ru/98-扩展设定建议清单.md","lastUpdated":null}'),e={name:"ru/98-扩展设定建议清单.md"};function i(l,t,o,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="список-предложении-по-расширенным-настроикам" tabindex="-1">Список Предложений по Расширенным Настройкам <a class="header-anchor" href="#список-предложении-по-расширенным-настроикам" aria-label="Permalink to &quot;Список Предложений по Расширенным Настройкам&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>98</td></tr><tr><td>Модуль</td><td>Приложения и справочные материалы</td></tr><tr><td>Ключевые слова</td><td>расширенные настройки, предложения по творчеству, направления сеттинга, открытость, области для разработки</td></tr></tbody></table><h2 id="i-пояснения" tabindex="-1">I. Пояснения <a class="header-anchor" href="#i-пояснения" aria-label="Permalink to &quot;I. Пояснения&quot;">​</a></h2><p>Настоящий документ перечисляет направления и предложения, доступные для расширенного творчества в системе сеттинга Симбиотической Цивилизации Якоря, имея целью дать создателям сеттинга вдохновение и ориентиры, помочь им вносить ценные расширения в существующие рамки. Список классифицирован по модулям; каждое направление расширения включает описание направления, ценность расширения, связь с существующим сеттингом и творческие предложения. Следует подчеркнуть, что этот список носит лишь рекомендательный характер; создатели могут свободно творить при условии соблюдения согласованности сеттинга, а также могут разрабатывать совершенно новые направления, не охваченные списком. Все расширенные настройки должны пройти проверку по Списку Самопроверки Противоречий Сеттинга (документ 97) до официального включения.</p><h2 id="ii-направления-расширения-мировоззрения-и-основных-настроек" tabindex="-1">II. Направления расширения мировоззрения и основных настроек <a class="header-anchor" href="#ii-направления-расширения-мировоззрения-и-основных-настроек" aria-label="Permalink to &quot;II. Направления расширения мировоззрения и основных настроек&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Номер</th><th>Направление расширения</th><th>Ценность расширения</th><th>Связанные настройки</th><th>Творческие предложения</th></tr></thead><tbody><tr><td>E01</td><td>Существования за границей вселенной</td><td>Исследовать, существуют ли другие вселенные или высшие измерения за сетью законов Вселенной Хэнъюань, давая сеттингу более грандиозную космологию</td><td>Документы 00, 28</td><td>Можно задать существование «космической стены», а также истории крайне редких исследователей, прорывающихся сквозь космическую стену, закладывая основу будущего межвселенского взаимодействия</td></tr><tr><td>E02</td><td>Сущность космической воли</td><td>Глубоко исследовать, существует ли на дне сети законов некая «космическая воля», и её связь с механизмом Якоря</td><td>Документы 00, 20</td><td>Космическую волю можно задать как неперсонифицированное самоорганизующееся явление законов, а не конкретное божество, сохраняя позицию «Реальность как основа»</td></tr><tr><td>E03</td><td>Утраченные цивилизации до-якорной эпохи</td><td>Подробно задать некогда блиставшие, но ныне исчезнувшие цивилизации до-якорной эпохи, обогащая историческую глубину</td><td>Документы 71, 93</td><td>Можно задать 3–5 показательных утраченных цивилизаций, каждая со своей уникальной системой культивации, культурой и причиной гибели, давая материал для археологических настроек</td></tr><tr><td>E04</td><td>Философские школы концепции симбиоза</td><td>В больших рамках «против хищничества, за симбиоз» задать различные интерпретации концепции симбиоза разными философскими школами</td><td>Документы 04, 03</td><td>Можно задать школы «радикального симбиоза», «умеренного симбиоза», «экологического симбиоза», «технологического симбиоза» и др.; их идейное противостояние может стать важным сюжетным напряжением</td></tr></tbody></table><h2 id="iii-направления-расширения-системы-культивации" tabindex="-1">III. Направления расширения системы культивации <a class="header-anchor" href="#iii-направления-расширения-системы-культивации" aria-label="Permalink to &quot;III. Направления расширения системы культивации&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Номер</th><th>Направление расширения</th><th>Ценность расширения</th><th>Связанные настройки</th><th>Творческие предложения</th></tr></thead><tbody><tr><td>E05</td><td>Детальные методы одной системы</td><td>Подробно развернуть одну из Трёхсот Систем, включая конкретные методы культивации, способы прорыва стадий и частые ошибки</td><td>Документы 10–19, 91</td><td>Рекомендуется в первую очередь разворачивать Три Исходные Основы и системы категории прикладной инженерии, тесно связанные с технологией; детальный документ каждой системы может включать шаги культивации, формулы сознания, требования к ресурсам и предупреждения о рисках</td></tr><tr><td>E06</td><td>Комбинированные схемы совместного культивирования</td><td>Изучить совместимость совместного культивирования разных систем и спроектировать оптимальные многосистемные комбинации</td><td>Документы 10, 11–13</td><td>Можно задать «золотые комбинации» (например, Дедуктивная Итерация + Пространственные Правовые Принципы + Прикладная Инженерия) и различные нестандартные комбинации, анализируя преимущества и ограничения каждой</td></tr><tr><td>E07</td><td>Узкие места культивации и методы прорыва</td><td>Подробно задать узкие места, с которыми каждая система может столкнуться на разных стадиях, и множество методов их преодоления</td><td>Документы 14, 19</td><td>Можно задать разные типы узких мест, такие как «испытание демона сердца», «барьер законов» и «исходное препятствие», с соответствующими путями прорыва, добавляя глубину процессу культивации</td></tr><tr><td>E08</td><td>Особые конституции и адаптация к системам</td><td>Задать различные особые конституции (такие как врождённое Дао-тело, тело элементарного сродства, сильный датчик сознания) и их адаптационные связи с разными системами культивации</td><td>Документы 12, 51</td><td>Можно спроектировать «матрицу адаптации конституция–система», помогающую создателям быстро определить, для каких систем подходит та или иная конституция</td></tr><tr><td>E09</td><td>Детальная классификация ресурсов культивации</td><td>Детально классифицировать и задать различные ресурсы, необходимые для культивации (небесные материалы и земные сокровища, энергетические кристаллы, фрагменты законов и т. д.)</td><td>Документы 18, 65</td><td>Можно задать класс ресурсов, место происхождения, способ сбора, способ хранения, запреты использования и др., выстраивая полную экосистему ресурсов культивации</td></tr></tbody></table><h2 id="iv-направления-расширения-общественного-строя" tabindex="-1">IV. Направления расширения общественного строя <a class="header-anchor" href="#iv-направления-расширения-общественного-строя" aria-label="Permalink to &quot;IV. Направления расширения общественного строя&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Номер</th><th>Направление расширения</th><th>Ценность расширения</th><th>Связанные настройки</th><th>Творческие предложения</th></tr></thead><tbody><tr><td>E10</td><td>Конкретные социальные формы Пяти типов</td><td>Подробно развернуть конкретные социальные системы, экономические модели и культурные особенности каждого из Пяти типов симбиотических цивилизаций</td><td>Документы 30–35</td><td>Для каждого типа можно задать типичный городской облик, семейную структуру, образовательную модель, праздники и торжества, делая пять типов каждый по-своему особенным</td></tr><tr><td>E11</td><td>Планировка и строительство симбиотических городов</td><td>Задать концепции планировки, архитектурные стили, инфраструктуру и функциональное зонирование городов симбиотической цивилизации</td><td>Документы 39, 60</td><td>Можно спроектировать разные типы городских форм: «вертикальный симбиотический город», «экологически вложенный город», «город со складыванием пространства» и др.</td></tr><tr><td>E12</td><td>Детальное функционирование системы образования</td><td>Подробно задать полный механизм функционирования симбиотической образовательной системы — от дошкольного образования до высшего и культивационного образования</td><td>Документы 37, 43</td><td>Можно задать систему курсов, способы оценки, систему наставников, межрасовые образовательные планы и др.</td></tr><tr><td>E13</td><td>Детальное функционирование системы здравоохранения</td><td>Подробно задать механизм функционирования симбиотической системы здравоохранения, включая сочетание обычной медицины и культивационной медицины</td><td>Документы 38, 44</td><td>Можно задать систему больниц, процедуры возмещения по медицинской страховке, особые нормы культивационного лечения, межрасовые медицинские планы и др.</td></tr><tr><td>E14</td><td>Система социального обеспечения</td><td>Подробно задать систему социального обеспечения симбиотической цивилизации, включая пенсии, пособия по безработице и помощь</td><td>Документы 32, 08</td><td>Можно задать условия подачи заявлений, стандарты выплат, источники финансирования и механизмы надзора</td></tr></tbody></table><h2 id="v-направления-расширения-права-и-управления" tabindex="-1">V. Направления расширения права и управления <a class="header-anchor" href="#v-направления-расширения-права-и-управления" aria-label="Permalink to &quot;V. Направления расширения права и управления&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Номер</th><th>Направление расширения</th><th>Ценность расширения</th><th>Связанные настройки</th><th>Творческие предложения</th></tr></thead><tbody><tr><td>E15</td><td>Типичные юридические дела</td><td>Написать типичные дела, рассматриваемые Симбиотическим Судом, показывая применение закона на практике</td><td>Документы 40–49, 92</td><td>Можно написать показательные дела: «дело о монополии ресурсов культивации», «дело о компенсации за межплоскостное загрязнение», «дело о правах тёмных замещающих сущностей» и др.</td></tr><tr><td>E16</td><td>Система местного самоуправления</td><td>Подробно задать системы самоуправления и разделение полномочий каждой звёздной области и каждой плоскости в рамках конституции</td><td>Документы 40, 49</td><td>Можно задать модели самоуправления разных автономных единиц, их отношения с центральным правительством, процедуры разработки автономных уставов и др.</td></tr><tr><td>E17</td><td>Избирательная и демократическая системы</td><td>Подробно задать избирательную систему представителей Собрания Якоря и механизм демократических решений</td><td>Документы 32, 49</td><td>Можно задать разделение избирательных округов, квалификацию кандидатов, избирательные процедуры, способы голосования, систему сроков полномочий и др.</td></tr><tr><td>E18</td><td>Механизм исполнения законов</td><td>Подробно задать механизм исполнения законов, включая правоохранительные органы, процедуры исполнения и принудительные меры</td><td>Документы 48, 49</td><td>Можно задать организационную структуру, полномочия, процедуры исполнения и механизмы надзора правоохранительных органов</td></tr></tbody></table><h2 id="vi-направления-расширения-жизни-и-рас" tabindex="-1">VI. Направления расширения жизни и рас <a class="header-anchor" href="#vi-направления-расширения-жизни-и-рас" aria-label="Permalink to &quot;VI. Направления расширения жизни и рас&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Номер</th><th>Направление расширения</th><th>Ценность расширения</th><th>Связанные настройки</th><th>Творческие предложения</th></tr></thead><tbody><tr><td>E19</td><td>Детальные настройки отдельной расы</td><td>Подробно развернуть одну расу из Реестра Десяти Тысяч Рас, включая физиологические особенности, социальную структуру, культурные традиции и историческую эволюцию</td><td>Документы 50–52, 94</td><td>Рекомендуется в первую очередь разворачивать показательные расы: Расу Дракона (Lóng Zú), Расу Эльфа (Jīnglíng Zú), Расу Машины (Jīxiè Zú), Расу Тела Сознания (Yìshítǐ Zú); каждая раса может включать язык, религию, искусство и обычаи</td></tr><tr><td>E20</td><td>Конкретные случаи аномальной жизни</td><td>Задать конкретных индивидов или группы аномальной жизни, показывая практическое применение трёх типов процедур обращения</td><td>Документы 53–54</td><td>Можно задать случаи: «дрейфующий в пустоте», «жизнь из фрагментов времени», «паразит законов» и др.</td></tr><tr><td>E21</td><td>Конкретные типы аномальной энергии</td><td>Подробно задать характеристики, источники, применения и методы контроля различных аномальных энергий</td><td>Документы 55–56</td><td>Можно задать типы: «причинная энергия», «энергия сознания», «энергия временного эха» и др.</td></tr><tr><td>E22</td><td>Конкретные случаи тёмных замещающих сущностей</td><td>Задать конкретные личные истории тёмных замещающих сущностей, показывая практическое применение Этки Двойной Души и обращения четырёх ветвей</td><td>Документы 57–59</td><td>Можно написать истории случаев разных типов тёмных замещающих сущностей, исследуя этические дилеммы сосуществования двух душ</td></tr><tr><td>E23</td><td>Потомки межрасовой интеграции</td><td>Задать особенности и культуру смешанных рас, рождённых от браков между разными расами</td><td>Документы 52, 77</td><td>Можно задать смешанные расы: «полуэльф», «драконорождённый», «механический бионический человек», исследуя их идентичность и культурное слияние</td></tr></tbody></table><h2 id="vii-направления-расширения-технологии-и-энергии" tabindex="-1">VII. Направления расширения технологии и энергии <a class="header-anchor" href="#vii-направления-расширения-технологии-и-энергии" aria-label="Permalink to &quot;VII. Направления расширения технологии и энергии&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Номер</th><th>Направление расширения</th><th>Ценность расширения</th><th>Связанные настройки</th><th>Творческие предложения</th></tr></thead><tbody><tr><td>E24</td><td>Детальные принципы отдельной технологии</td><td>Дать детальный разбор принципов ключевой технологии (например, Зеркало Репликации, изолированное пространство, инженеризация Плода Умножения)</td><td>Документы 60–69, 63–64</td><td>Можно задать историю развития, ключевые компоненты, рабочий процесс, технические ограничения и направления модернизации технологии</td></tr><tr><td>E25</td><td>Детальная классификация культивационного оборудования</td><td>Задать классификацию, функции, классы и способы применения различных вспомогательных культивационных устройств</td><td>Документы 61, 67</td><td>Можно задать типы устройств: «капсула культивации», «детектор законов», «преобразователь энергии», «усилитель сознания» и др.</td></tr><tr><td>E26</td><td>Детальные настройки аппаратуры Якоря</td><td>Подробно задать структуру, функции, строительство и обслуживание аппаратных объектов Якоря</td><td>Документы 20, 67</td><td>Можно задать ключевые компоненты, энергоснабжение, цикл обслуживания и устранение неисправностей искусственных Якорей</td></tr><tr><td>E27</td><td>Межплоскостная коммуникационная технология</td><td>Подробно задать технические принципы, типы оборудования, коммуникационные протоколы и механизмы безопасности межплоскостной связи</td><td>Документы 66, 81</td><td>Можно задать разные способы связи: «связь через якорные волны», «связь со складыванием пространства», «связь через резонанс сознания» и др.</td></tr></tbody></table><h2 id="viii-направления-расширения-истории-и-событии" tabindex="-1">VIII. Направления расширения истории и событий <a class="header-anchor" href="#viii-направления-расширения-истории-и-событии" aria-label="Permalink to &quot;VIII. Направления расширения истории и событий&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Номер</th><th>Направление расширения</th><th>Ценность расширения</th><th>Связанные настройки</th><th>Творческие предложения</th></tr></thead><tbody><tr><td>E28</td><td>Детальные описания крупных исторических событий</td><td>Дать детальное историческое описание одного крупного события из хроники</td><td>Документы 70–79, 93</td><td>Можно подробно описать весь процесс событий: «событие открытия Трёхсот Систем», «реализация Стратегии активации 20 %», «первая веха возвышения» и др.</td></tr><tr><td>E29</td><td>Биографии исторических личностей</td><td>Написать подробные биографии ключевых личностей, обогащая гуманистическую глубину истории</td><td>Документ 95</td><td>Можно написать биографии ключевых личностей: «Xuánhéng Zǐ», «Gòngshēng Zǐ», «Lìxiàn Gōng», «Sānbǎi Shī» и др.</td></tr><tr><td>E30</td><td>Гипотетический анализ исторических поворотных точек</td><td>Проанализировать, как отличалось бы развитие симбиотической цивилизации, пойди определённое историческое событие иным путём</td><td>Документы 70–79</td><td>Можно сделать гипотетические анализы: «если бы Симбиотическая Конституция не была принята», «если бы Стратегия активации 20 % провалилась» и др., показывая случайность истории</td></tr><tr><td>E31</td><td>Детальные записи археологических открытий</td><td>Задать детальные открытия и результаты исследований некой межплоскостной археологии</td><td>Документы 84–87</td><td>Можно задать «археологическое открытие некой утраченной цивилизации», «результаты археологии возврата времени ключевого исторического узла» и др.</td></tr></tbody></table><h2 id="ix-направления-расширения-межплоскостного-и-времени" tabindex="-1">IX. Направления расширения межплоскостного и времени <a class="header-anchor" href="#ix-направления-расширения-межплоскостного-и-времени" aria-label="Permalink to &quot;IX. Направления расширения межплоскостного и времени&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Номер</th><th>Направление расширения</th><th>Ценность расширения</th><th>Связанные настройки</th><th>Творческие предложения</th></tr></thead><tbody><tr><td>E32</td><td>Детальные настройки конкретных плоскостей</td><td>Задать параметры законов, формы цивилизации, географическую среду и историю конкретной плоскости</td><td>Документы 80, 81</td><td>Можно задать разные типы конкретных плоскостей: «высокомагическая плоскость», «технологическая плоскость», «дикая плоскость», «плоскость сознания» и др.</td></tr><tr><td>E33</td><td>Случаи межплоскостной дипломатии</td><td>Задать конкретные случаи установления дипломатических отношений симбиотической цивилизации с другими плоскостными цивилизациями</td><td>Документы 81, 88</td><td>Можно задать конкретные дипломатические события: первый контакт, переговоры об установлении отношений, культурный обмен, торговые соглашения и др.</td></tr><tr><td>E34</td><td>Конкретные случаи возврата времени</td><td>Задать конкретный процесс, открытия и последствия некой операции возврата времени</td><td>Документы 82–83, 89</td><td>Можно задать случаи: «разгадка некой исторической тайны через возврат», «восстановление некой вымершей цивилизации через возврат» и др.</td></tr><tr><td>E35</td><td>Детальные записи событий временных парадоксов</td><td>Задать полный процесс некоего события временного парадокса, включая его возникновение, экстренную реакцию и причинный ремонт</td><td>Документ 89</td><td>Можно написать полную запись обработки мелкомасштабного события парадокса, показывая практическую работу механизмов предотвращения и контроля</td></tr><tr><td>E36</td><td>Межплоскостные конфликты и их разрешение</td><td>Задать конфликты между симбиотической цивилизацией и другими плоскостными цивилизациями и процесс мирного разрешения</td><td>Документы 81, 88</td><td>Можно задать разные типы межплоскостных конфликтов: споры о ресурсах, культурные конфликты, пограничные споры и др.</td></tr></tbody></table><h2 id="x-творческие-принципы-расширенных-настроек" tabindex="-1">X. Творческие принципы расширенных настроек <a class="header-anchor" href="#x-творческие-принципы-расширенных-настроек" aria-label="Permalink to &quot;X. Творческие принципы расширенных настроек&quot;">​</a></h2><p>При создании расширенных настроек следует соблюдать следующие принципы:</p><ol><li><strong>Согласованность прежде всего</strong> : все расширенные настройки должны оставаться логически согласованными с существующим сеттингом и проходить проверку по Списку Самопроверки Противоречий Сеттинга.</li><li><strong>Реальность как основа</strong> : расширенные настройки должны разумно выводиться на основе объективных законов, избегая чистой фантазии и разрушения сеттинга.</li><li><strong>Симбиотическая позиция</strong> : расширенные настройки должны всегда придерживаться ключевой позиции против хищничества и за симбиоз, не допускается оправдание хищнических действий.</li><li><strong>Открытость</strong> : расширенные настройки должны сохранять определённую открытость, оставляя место для дальнейших расширений.</li><li><strong>Практичность</strong> : расширенные настройки должны иметь практическую творческую ценность, давая полезный материал для создания историй, дизайна игр и теоретических обсуждений.</li></ol><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Список Предложений по Расширенным Настройкам — это «открытая дверь» системы сеттинга Симбиотической Цивилизации Якоря. Он показывает, что эта система сеттинга не закрытый, завершённый продукт, а живая система, непрерывно растущая и обогащающаяся. Тридцать шесть направлений расширения — лишь отправная точка; настоящая творческая сила сеттинга исходит из воображения и энтузиазма каждого участника. Пока соблюдается основной принцип согласованности сеттинга, каждое ценное расширение станет незаменимым компонентом великого повествования Симбиотической Цивилизации Якоря.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (Список Самопроверки Противоречий Сеттинга)</li><li>99-文档版本与维护说明 (Версия Документов и Пояснения по Обслуживанию)</li><li>96-常见问题FAQ (Часто Задаваемые Вопросы (FAQ))</li></ul>',27)])])}const E=d(e,[["render",i]]);export{u as __pageData,E as default};
